statement:
A dieter eats `calories[i]` calories on day `i`. Every run of `k` consecutive days (days `i` through `i + k - 1`, for each `0 <= i <= calories.length - k`) is judged on its total `T`. The score starts at 0, and each run changes it as follows:

- if `T < lower`, the score drops by 1;
- if `T > upper`, the score rises by 1;
- otherwise the score stays the same.

Return the final score once every run has been judged. It may be negative.

validator:
function validate([calories, k, lower, upper]) {
  if (!Array.isArray(calories) || calories.length < 1 || calories.length > 100000) return 'calories needs 1 to 100000 days.';
  if (calories.some(c => !Number.isInteger(c) || c < 0 || c > 20000)) return 'Each day has 0 to 20000 calories.';
  if (!Number.isInteger(k) || k < 1 || k > calories.length) return 'k is between 1 and the number of days.';
  if (!Number.isInteger(lower) || !Number.isInteger(upper) || lower < 0 || lower > upper || upper > 2147483647) return 'Need 0 <= lower <= upper (32-bit integers).';
  return null;
}

reference:
function dietPlanPerformance(calories, k, lower, upper) {
  let points = 0;
  let total = 0;

  for (let day = 0; day < calories.length; day++) {
    total += calories[day];
    if (day >= k) {
      total -= calories[day - k];
    }
    if (day < k - 1) {
      continue;
    }
    if (total < lower) {
      points--;
    } else if (total > upper) {
      points++;
    }
  }
  return points;
}

