function dietPlanPerformance(calories, k, lower, upper) {
  let score = 0;
  for (let start = 0; start + k <= calories.length; start++) {
    const sum = calories.slice(start, start + k).reduce((a, b) => a + b, 0);
    score += sum < lower ? -1 : sum > upper ? 1 : 0;
  }
  return score;
}

