    const n = 1500 + Math.floor(rand() * 501);
    const k = rand() < 0.5 ? 1 + Math.floor(rand() * 20) : 1 + Math.floor(rand() * n);
    const calories = Array.from({ length: n }, () => Math.floor(rand() * 20001));
    const spread = Math.ceil(Math.sqrt(k) * 6000);
    const lower = Math.max(0, k * 10000 - Math.floor(rand() * spread));
    const upper = lower + Math.floor(rand() * spread);
    return [calories, k, lower, upper];
  }
  const n = 1 + Math.floor(rand() * 8);
  const k = 1 + Math.floor(rand() * n);
  const top = rand() < 0.2 ? 0 : 1 + Math.floor(rand() * 10);
  const calories = Array.from({ length: n }, () => Math.floor(rand() * (top + 1)));
  const lower = Math.floor(rand() * (k * top + 2));
  const upper = lower + Math.floor(rand() * (k * 3 + 1));
  return [calories, k, lower, upper];
}
